package pt.qpetiscos.agenda;import android.content.*;public class WidgetClick extends BroadcastReceiver{public void onReceive(Context c,Intent i){int id=i.getIntExtra("wid",-1);String op=i.getStringExtra("op"),event=i.getStringExtra("event");if(id<0||op==null||event==null||!event.matches("[a-fA-F0-9-]{36}"))return;if("view".equals(op)){try{WidgetAgenda.open(c,id,"qp=view&id="+event+"&date="+WidgetAgenda.date(c,id)).send();}catch(Exception ignored){}return;}if(!java.util.Arrays.asList("expand","toggle","delete").contains(op))return;try{WidgetAgenda.action(c,i.getBooleanExtra("take",false)?TakeawayWidget.class:FullWidget.class,id,"qp."+op,event,i.getBooleanExtra("done",false)).send();}catch(Exception ignored){}}}
